            "Ghi nhớ và kể lại các câu chuyện âm nhạc một cách lôi cuốn, rút ra được ý nghĩa nhân văn sâu sắc.",
            "Luôn là nhân tố đi đầu trong các hoạt động văn nghệ của lớp và tích cực hỗ trợ bạn bè cùng tiến bộ.",
            "Thực hiện bài đọc nhạc số 1, số 2 trôi chảy cả về cao độ, trường độ và nhịp độ quy định.",
            "Biết ứng tác lời mới cho giai điệu một cách thông minh, vần điệu và phù hợp với chủ đề bài học.",
            "Sử dụng thành thạo các ký hiệu âm nhạc như dấu luyến, dấu nối, dấu lặng vào việc đọc nhạc.",
            "Thể hiện sự đam mê âm nhạc cháy bỏng, luôn tìm tòi học hỏi các kiến thức mới ngoài sách giáo khoa.",
            "Biết lắng nghe và điều chỉnh giọng hát để hòa quyện hoàn hảo trong các bài hát đồng ca, tốp ca.",
