            "Biết vâng lời and thực hiện đúng các quy tắc đảm bảo an toàn khi làm việc with các dụng cụ mĩ thuật sắc nhọn ạ.",
            "Có ý thức giữ gìn môi trường học tập sạch đẹp thông qua việc thu dọn giấy vụn sau mỗi giờ thực hành mĩ thuật.",
